package main

import (
	"fmt"
	"strings"
)

type Position struct {
	File string
	Line int
}

func (p Position) String() string { return fmt.Sprintf("%s:%d", p.File, p.Line) }

const variadicName = "__VA_ARGS__"

var builtins = map[string]bool{"__LINE__": true, "__FILE__": true, "__COUNTER__": true}

type Macro struct {
	Name               string
	Function, Variadic bool
	Parameters         []string
	Replacement        []Token
	Position
	MainFile         bool
	Expanded, Tested int
}

func (m *Macro) signature() string {
	if !m.Function {
		return m.Name
	}
	parameters := append([]string{}, m.Parameters...)
	if m.Variadic {
		parameters[len(parameters)-1] = "..."
	}
	return m.Name + "(" + strings.Join(parameters, ", ") + ")"
}
func checkName(tokens []Token, directive string) string {
	if len(tokens) == 0 {
		return "no macro name given in #" + directive + " directive"
	}
	if tokens[0].Kind != "identifier" {
		return "macro names must be identifiers"
	}
	name := tokens[0].Spelling
	if name == "defined" {
		return `"defined" cannot be used as a macro name`
	}
	if builtins[name] {
		if directive == "define" {
			return `cannot redefine builtin macro "` + name + `"`
		}
		return `cannot undefine builtin macro "` + name + `"`
	}
	return ""
}
func parseDefinition(tokens []Token, pos Position, main bool) (*Macro, string) {
	if error := checkName(tokens, "define"); error != "" {
		return nil, error
	}
	m := &Macro{Name: tokens[0].Spelling, Position: pos, MainFile: main}
	if m.Name == variadicName {
		return nil, `"__VA_ARGS__" can only appear in the expansion of a variadic macro`
	}
	index := 1
	if index < len(tokens) && tokens[index].Spelling == "(" && !tokens[index].Space {
		m.Function = true
		index++
		if index == len(tokens) {
			return nil, "missing ')' in macro parameter list"
		}
		if tokens[index].Spelling == ")" {
			index++
		} else {
			seen := map[string]bool{}
			for {
				if index == len(tokens) {
					return nil, "missing ')' in macro parameter list"
				}
				token := tokens[index]
				index++
				parameter := token.Spelling
				if parameter == "..." {
					m.Variadic = true
					parameter = variadicName
				} else if token.Kind == "identifier" {
					if parameter == variadicName {
						return nil, `"__VA_ARGS__" can only appear in the expansion of a variadic macro`
					}
					if seen[parameter] {
						return nil, `duplicate macro parameter "` + parameter + `"`
					}
				} else {
					return nil, `expected parameter name, found "` + parameter + `"`
				}
				seen[parameter] = true
				m.Parameters = append(m.Parameters, parameter)
				if index == len(tokens) {
					return nil, "missing ')' in macro parameter list"
				}
				next := tokens[index].Spelling
				index++
				if next == ")" {
					break
				}
				if m.Variadic {
					return nil, `expected ')' after "...", found "` + next + `"`
				}
				if next != "," {
					return nil, `expected ',' or ')', found "` + next + `"`
				}
			}
		}
	}
	m.Replacement = copyTokens(tokens[index:])
	if len(m.Replacement) > 0 {
		m.Replacement[0].Space = false
		if m.Replacement[0].Spelling == "##" || m.Replacement[len(m.Replacement)-1].Spelling == "##" {
			return nil, "'##' cannot appear at either end of a macro expansion"
		}
	}
	parameters := map[string]bool{}
	for _, parameter := range m.Parameters {
		parameters[parameter] = true
	}
	for i, token := range m.Replacement {
		if token.Kind == "identifier" && token.Spelling == variadicName && !m.Variadic {
			return nil, `"__VA_ARGS__" can only appear in the expansion of a variadic macro`
		}
		if token.Spelling == "#" && m.Function && (i+1 == len(m.Replacement) || m.Replacement[i+1].Kind != "identifier" || !parameters[m.Replacement[i+1].Spelling]) {
			return nil, "'#' is not followed by a macro parameter"
		}
	}
	return m, ""
}
func (m *Macro) identical(other *Macro) bool {
	if m.Function != other.Function || m.Variadic != other.Variadic || len(m.Parameters) != len(other.Parameters) || len(m.Replacement) != len(other.Replacement) {
		return false
	}
	for i, p := range m.Parameters {
		if p != other.Parameters[i] {
			return false
		}
	}
	for i, t := range m.Replacement {
		u := other.Replacement[i]
		if t.Spelling != u.Spelling || t.Space != u.Space {
			return false
		}
	}
	return true
}

package main

import (
	"fmt"
	"strconv"
	"strings"
)

type Expander struct {
	Macros        map[string]*Macro
	Diagnostic    func(Position, string, string)
	Counter       int
	BuiltinCounts map[string]int
}

func union(a, b map[string]bool) map[string]bool {
	out := map[string]bool{}
	for name := range a {
		out[name] = true
	}
	for name := range b {
		out[name] = true
	}
	return out
}
func intersection(a, b map[string]bool) map[string]bool {
	out := map[string]bool{}
	for name := range a {
		if b[name] {
			out[name] = true
		}
	}
	return out
}
func (e *Expander) error(context *Inclusion, t Token, message string) {
	e.Diagnostic(context.position(t.Line), "error", message)
}
func (e *Expander) builtin(t Token, context *Inclusion) Token {
	e.BuiltinCounts[t.Spelling]++
	kind, spelling := "number", ""
	switch t.Spelling {
	case "__FILE__":
		kind = "string"
		spelling = `"` + context.DisplayFile + `"`
	case "__LINE__":
		spelling = strconv.Itoa(context.position(t.Line).Line)
	case "__COUNTER__":
		spelling = strconv.Itoa(e.Counter)
		e.Counter++
	}
	return Token{Kind: kind, Spelling: spelling, Line: t.Line, Space: t.Space}
}
func (e *Expander) collect(pending []Token, m *Macro, t Token, context *Inclusion) (map[string][]Token, int, Token, bool) {
	arguments := [][]Token{{}}
	separators := []Token{}
	nesting, consumed := 0, 0
	var closing Token
	for index := 1; index < len(pending); index++ {
		current := pending[index]
		if current.Spelling == ")" && nesting == 0 {
			closing = current
			consumed = index + 1
			break
		}
		if current.Spelling == "," && nesting == 0 {
			separators = append(separators, current)
			arguments = append(arguments, []Token{})
		} else {
			if current.Spelling == "(" {
				nesting++
			} else if current.Spelling == ")" {
				nesting--
			}
			arguments[len(arguments)-1] = append(arguments[len(arguments)-1], current)
		}
	}
	if consumed == 0 {
		e.error(context, t, `unterminated argument list invoking macro "`+m.Name+`"`)
		return nil, 0, Token{}, false
	}
	count, fixed := len(arguments), len(m.Parameters)
	if m.Variadic {
		fixed--
	}
	message := ""
	switch {
	case !m.Variadic && fixed == 0 && (count != 1 || len(arguments[0]) > 0):
		message = fmt.Sprintf("macro %q passed %d arguments, but takes just 0", m.Name, count)
	case count < fixed:
		message = fmt.Sprintf("macro %q requires %d arguments, but only %d given", m.Name, fixed, count)
	case count > fixed && !m.Variadic:
		message = fmt.Sprintf("macro %q passed %d arguments, but takes just %d", m.Name, count, fixed)
	}
	if message != "" {
		e.error(context, t, message)
		return nil, 0, Token{}, false
	}
	raw := map[string][]Token{}
	for i := 0; i < fixed; i++ {
		raw[m.Parameters[i]] = copyTokens(arguments[i])
	}
	if m.Variadic {
		variable := []Token{}
		for i := fixed; i < count; i++ {
			if i > fixed {
				variable = append(variable, separators[i-1])
			}
			variable = append(variable, arguments[i]...)
		}
		raw[variadicName] = variable
	}
	return raw, consumed, closing, true
}
func stringize(tokens []Token, sharp Token) Token {
	var value strings.Builder
	value.WriteByte('"')
	for i, t := range tokens {
		if i > 0 && t.Space {
			value.WriteByte(' ')
		}
		spelling := t.Spelling
		if t.Kind == "string" || t.Kind == "character" {
			spelling = strings.ReplaceAll(spelling, `\`, `\\`)
			spelling = strings.ReplaceAll(spelling, `"`, `\"`)
		}
		value.WriteString(spelling)
	}
	value.WriteByte('"')
	return Token{Kind: "string", Spelling: value.String(), Line: sharp.Line, Space: sharp.Space}
}
func (e *Expander) paste(left, right, t Token, context *Inclusion) []Token {
	if left.Kind == "placemarker" {
		right.Space = left.Space
		return []Token{right}
	}
	if right.Kind == "placemarker" {
		return []Token{left}
	}
	spelling := left.Spelling + right.Spelling
	if kind, ok := singleToken(spelling); ok {
		return []Token{{Kind: kind, Spelling: spelling, Line: left.Line, Space: left.Space, Hide: intersection(left.Hide, right.Hide)}}
	}
	e.error(context, t, `pasting "`+left.Spelling+`" and "`+right.Spelling+`" does not give a valid preprocessing token`)
	right.Space = false
	return []Token{left, right}
}

type SubstitutionItem struct {
	Tokens   []Token
	Paste    bool
	Operator Token
}

func (e *Expander) substitute(m *Macro, raw map[string][]Token, t Token, hide map[string]bool, context *Inclusion) []Token {
	replacement := m.Replacement
	items := []SubstitutionItem{}
	expanded := map[string][]Token{}
	for index := 0; index < len(replacement); {
		current := replacement[index]
		if current.Spelling == "#" && m.Function {
			parameter := replacement[index+1].Spelling
			items = append(items, SubstitutionItem{Tokens: []Token{stringize(raw[parameter], current)}})
			index += 2
			continue
		}
		if current.Spelling == "##" {
			items = append(items, SubstitutionItem{Paste: true, Operator: current})
		} else if sequence, parameter := raw[current.Spelling]; current.Kind == "identifier" && parameter {
			adjacent := index > 0 && replacement[index-1].Spelling == "##" || index+1 < len(replacement) && replacement[index+1].Spelling == "##"
			if !adjacent {
				cached, done := expanded[current.Spelling]
				if !done {
					cached = e.expand(sequence, context)
					expanded[current.Spelling] = cached
				}
				sequence = cached
			}
			sequence = copyTokens(sequence)
			if len(sequence) > 0 {
				sequence[0].Space = current.Space
			} else {
				sequence = []Token{{Kind: "placemarker", Line: current.Line, Space: current.Space}}
			}
			items = append(items, SubstitutionItem{Tokens: sequence})
		} else {
			items = append(items, SubstitutionItem{Tokens: []Token{current}})
		}
		index++
	}
	pasted := []Token{}
	for index := 0; index < len(items); {
		item := items[index]
		if !item.Paste {
			pasted = append(pasted, item.Tokens...)
			index++
			continue
		}
		left := pasted[len(pasted)-1]
		pasted = pasted[:len(pasted)-1]
		right := items[index+1].Tokens
		if items[index+1].Paste {
			right = []Token{items[index+1].Operator}
		}
		pasted = append(pasted, e.paste(left, right[0], t, context)...)
		pasted = append(pasted, right[1:]...)
		index += 2
	}
	result := []Token{}
	carry := false
	for _, current := range pasted {
		if current.Kind == "placemarker" {
			carry = carry || current.Space
			continue
		}
		current.Line = t.Line
		current.Space = current.Space || carry
		carry = false
		current.Hide = union(current.Hide, hide)
		result = append(result, current)
	}
	if len(result) > 0 {
		result[0].Space = t.Space
	}
	return result
}
func (e *Expander) expand(sequence []Token, context *Inclusion) []Token {
	pending := copyTokens(sequence)
	result := []Token{}
	for len(pending) > 0 {
		t := pending[0]
		pending = pending[1:]
		if t.Kind != "identifier" || t.Hide[t.Spelling] {
			result = append(result, t)
			continue
		}
		if builtins[t.Spelling] {
			result = append(result, e.builtin(t, context))
			continue
		}
		m := e.Macros[t.Spelling]
		if m == nil || m.Function && (len(pending) == 0 || pending[0].Spelling != "(") {
			result = append(result, t)
			continue
		}
		raw := map[string][]Token{}
		hide := union(t.Hide, map[string]bool{m.Name: true})
		if m.Function {
			collected, consumed, closing, ok := e.collect(pending, m, t, context)
			if !ok {
				result = append(result, t)
				continue
			}
			raw = collected
			pending = pending[consumed:]
			hide = union(intersection(t.Hide, closing.Hide), map[string]bool{m.Name: true})
		}
		replacement := e.substitute(m, raw, t, hide, context)
		m.Expanded++
		if len(replacement) == 0 && t.Space && len(pending) > 0 {
			pending[0].Space = true
		}
		pending = append(replacement, pending...)
	}
	return result
}

package main

import (
	"regexp"
	"strconv"
	"strings"
)

type ExpressionError struct{ Message string }
type ConditionExpr struct {
	Kind, Op, Name string
	Value          int64
	Children       []*ConditionExpr
}

var hexPattern = regexp.MustCompile(`^0[xX][0-9a-fA-F]+$`)
var octalPattern = regexp.MustCompile(`^0[0-7]*$`)
var decimalPattern = regexp.MustCompile(`^[1-9][0-9]*$`)

func integerConstant(spelling string) (int64, string) {
	text := spelling
	for _, suffix := range []string{"ll", "LL", "l", "L"} {
		if len(text) > len(suffix) && strings.HasSuffix(text, suffix) {
			text = strings.TrimSuffix(text, suffix)
			break
		}
	}
	base := 0
	if hexPattern.MatchString(text) {
		base = 16
		text = text[2:]
	} else if octalPattern.MatchString(text) {
		base = 8
	} else if decimalPattern.MatchString(text) {
		base = 10
	}
	if base == 0 {
		return 0, `invalid integer constant "` + spelling + `"`
	}
	value, _ := strconv.ParseInt(text, base, 64)
	return value, ""
}
func characterConstant(spelling string) (int64, string) {
	body := spelling[1 : len(spelling)-1]
	if len(body) == 1 && body[0] != '\'' && body[0] != '\\' {
		return int64(body[0]), ""
	}
	if len(body) == 2 && body[0] == '\\' {
		values := map[byte]int64{'n': 10, 't': 9, '\\': 92, '\'': 39, '"': 34, '0': 0}
		if value, ok := values[body[1]]; ok {
			return value, ""
		}
	}
	return 0, "invalid character constant " + spelling
}
func conditionPrecedence(op string) int {
	switch op {
	case "||":
		return 1
	case "&&":
		return 2
	case "|":
		return 3
	case "^":
		return 4
	case "&":
		return 5
	case "==", "!=":
		return 6
	case "<", ">", "<=", ">=":
		return 7
	case "<<", ">>":
		return 8
	case "+", "-":
		return 9
	case "*", "/", "%":
		return 10
	}
	return 0
}

type ExpressionParser struct {
	Tokens []Token
	Index  int
}

func (p *ExpressionParser) peek() string {
	if p.Index == len(p.Tokens) {
		return ""
	}
	return p.Tokens[p.Index].Spelling
}
func expressionError(message string) { panic(&ExpressionError{message}) }
func (p *ExpressionParser) expression() *ConditionExpr {
	first := p.binary(1)
	if p.peek() == "?" {
		p.Index++
		second := p.expression()
		if p.peek() != ":" {
			expressionError("'?' without following ':'")
		}
		p.Index++
		third := p.expression()
		return &ConditionExpr{Kind: "conditional", Children: []*ConditionExpr{first, second, third}}
	}
	return first
}
func (p *ExpressionParser) binary(minimum int) *ConditionExpr {
	left := p.unary()
	for {
		level := conditionPrecedence(p.peek())
		if level == 0 || level < minimum {
			break
		}
		op := p.peek()
		p.Index++
		right := p.binary(level + 1)
		left = &ConditionExpr{Kind: "binary", Op: op, Children: []*ConditionExpr{left, right}}
	}
	return left
}
func (p *ExpressionParser) unary() *ConditionExpr {
	if wordIn("+ - ! ~", p.peek()) {
		op := p.peek()
		p.Index++
		return &ConditionExpr{Kind: "unary", Op: op, Children: []*ConditionExpr{p.unary()}}
	}
	return p.primary()
}
func (p *ExpressionParser) primary() *ConditionExpr {
	if p.Index == len(p.Tokens) {
		expressionError("expected value at end of expression")
	}
	token := p.Tokens[p.Index]
	p.Index++
	switch token.Kind {
	case "number", "character":
		value, error := int64(0), ""
		if token.Kind == "number" {
			value, error = integerConstant(token.Spelling)
		} else {
			value, error = characterConstant(token.Spelling)
		}
		if error != "" {
			expressionError(error)
		}
		return &ConditionExpr{Kind: "constant", Value: value}
	case "identifier":
		return &ConditionExpr{Kind: "identifier", Name: token.Spelling}
	}
	if token.Spelling == "(" {
		e := p.expression()
		if p.peek() != ")" {
			expressionError("missing ')' in expression")
		}
		p.Index++
		return e
	}
	expressionError(`expected value before "` + token.Spelling + `"`)
	return nil
}
func parseCondition(tokens []Token, directive string) (tree *ConditionExpr, err *ExpressionError) {
	defer func() {
		if value := recover(); value != nil {
			if failure, ok := value.(*ExpressionError); ok {
				err = failure
			} else {
				panic(value)
			}
		}
	}()
	if len(tokens) == 0 {
		expressionError("#" + directive + " with no expression")
	}
	p := ExpressionParser{Tokens: tokens}
	tree = p.expression()
	if p.Index < len(tokens) {
		expressionError(`missing binary operator before "` + p.peek() + `"`)
	}
	return
}
func evaluateCondition(e *ConditionExpr, warning func(string)) (value int64, err *ExpressionError) {
	defer func() {
		if v := recover(); v != nil {
			if failure, ok := v.(*ExpressionError); ok {
				err = failure
			} else {
				panic(v)
			}
		}
	}()
	value = evalCondition(e, warning)
	return
}
func evalCondition(e *ConditionExpr, warning func(string)) int64 {
	switch e.Kind {
	case "constant":
		return e.Value
	case "identifier":
		warning(`identifier "` + e.Name + `" evaluates to 0`)
		return 0
	case "unary":
		a := evalCondition(e.Children[0], warning)
		switch e.Op {
		case "+":
			return a
		case "-":
			return -a
		case "!":
			if a == 0 {
				return 1
			}
			return 0
		case "~":
			return -a - 1
		}
	case "conditional":
		condition := evalCondition(e.Children[0], warning)
		if condition != 0 {
			return evalCondition(e.Children[1], warning)
		}
		return evalCondition(e.Children[2], warning)
	case "binary":
		a := evalCondition(e.Children[0], warning)
		if e.Op == "&&" && a == 0 {
			return 0
		}
		if e.Op == "||" && a != 0 {
			return 1
		}
		b := evalCondition(e.Children[1], warning)
		answer := false
		switch e.Op {
		case "+":
			return a + b
		case "-":
			return a - b
		case "*":
			return a * b
		case "/", "%":
			if b == 0 {
				expressionError("division by zero in #if")
			}
			q := a / b
			if e.Op == "/" {
				return q
			}
			return a - b*q
		case "<<":
			return a << uint(b)
		case ">>":
			return a >> uint(b)
		case "&":
			return a & b
		case "|":
			return a | b
		case "^":
			return a ^ b
		case "==":
			answer = a == b
		case "!=":
			answer = a != b
		case "<":
			answer = a < b
		case "<=":
			answer = a <= b
		case ">":
			answer = a > b
		case ">=":
			answer = a >= b
		case "&&", "||":
			answer = b != 0
		}
		if answer {
			return 1
		}
		return 0
	}
	return 0
}

package main

import (
	"os"
	"strings"
)

type FileData struct {
	Path                                        string
	Lines                                       []LogicalLine
	PhysicalLines                               int
	Guard                                       string
	Entered, Skipped, OutputLines, SkippedLines int
	Once                                        bool
}
type IncludeManager struct {
	Files map[string]*FileData
	Order []string
}

func directiveName(tokens []Token) string {
	if len(tokens) >= 2 && tokens[0].Spelling == "#" && tokens[1].Kind == "identifier" {
		return tokens[1].Spelling
	}
	return ""
}
func detectGuard(logical []LogicalLine) string {
	lines := [][]Token{}
	for _, line := range logical {
		if len(line.Tokens) > 0 {
			lines = append(lines, line.Tokens)
		}
	}
	if len(lines) == 0 {
		return ""
	}
	first, last := lines[0], lines[len(lines)-1]
	if len(first) != 3 || first[0].Spelling != "#" || first[1].Spelling != "ifndef" || first[1].Kind != "identifier" || first[2].Kind != "identifier" || len(last) != 2 || last[0].Spelling != "#" || last[1].Spelling != "endif" || last[1].Kind != "identifier" {
		return ""
	}
	depth := 0
	for i, line := range lines {
		name := directiveName(line)
		if wordIn("elif elifdef elifndef else", name) && depth == 1 {
			return ""
		}
		if wordIn("if ifdef ifndef", name) {
			depth++
		} else if name == "endif" {
			depth--
		}
		if depth == 0 && i != len(lines)-1 {
			return ""
		}
	}
	if depth != 0 {
		return ""
	}
	return first[2].Spelling
}
func (m *IncludeManager) search(name string, quoted bool) string {
	paths := []string{}
	if quoted {
		paths = append(paths, name)
	}
	paths = append(paths, "include/"+name)
	for _, path := range paths {
		if info, err := os.Stat("input/" + path); err == nil && !info.IsDir() {
			return path
		}
	}
	return ""
}
func (m *IncludeManager) load(path string) *FileData {
	if file := m.Files[path]; file != nil {
		return file
	}
	raw, err := os.ReadFile("input/" + path)
	if err != nil {
		panic(err)
	}
	source := string(raw)
	logical := lexSource(source)
	file := &FileData{Path: path, Lines: logical, PhysicalLines: strings.Count(source, "\n"), Guard: detectGuard(logical)}
	m.Files[path] = file
	m.Order = append(m.Order, path)
	return file
}

package main

import "strings"

type Token struct {
	Kind, Spelling string
	Line           int
	Space          bool
	Hide           map[string]bool
}
type LogicalLine struct {
	Tokens     []Token
	Start, End int
}

var punctuators = strings.Fields("... <<= >>= -> ++ -- << >> <= >= == != && || *= /= %= += -= &= ^= |= ## [ ] ( ) { } . & * + - ~ ! / % < > ^ | ? : ; = , #")

func identifierStart(c byte) bool { return c == '_' || c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' }
func digit(c byte) bool           { return c >= '0' && c <= '9' }
func wordIn(words, value string) bool {
	for _, word := range strings.Fields(words) {
		if word == value {
			return true
		}
	}
	return false
}
func readToken(source string, index int, header bool) (string, string, int) {
	c := source[index]
	n := len(source)
	if header && c == '<' {
		end := strings.IndexByte(source[index+1:], '>')
		newline := strings.IndexByte(source[index+1:], '\n')
		if end >= 0 && (newline < 0 || end < newline) {
			end += index + 2
			return "header", source[index:end], end
		}
	}
	if identifierStart(c) {
		end := index + 1
		for end < n && (identifierStart(source[end]) || digit(source[end])) {
			end++
		}
		return "identifier", source[index:end], end
	}
	if digit(c) || c == '.' && index+1 < n && digit(source[index+1]) {
		end := index + 1
		for end < n {
			if strings.ContainsRune("eEpP", rune(source[end])) && end+1 < n && (source[end+1] == '+' || source[end+1] == '-') {
				end += 2
			} else if identifierStart(source[end]) || digit(source[end]) || source[end] == '.' {
				end++
			} else {
				break
			}
		}
		return "number", source[index:end], end
	}
	if c == '\'' || c == '"' {
		end := index + 1
		for end < n && source[end] != '\n' {
			if source[end] == c {
				kind := "character"
				if c == '"' {
					kind = "string"
				}
				return kind, source[index : end+1], end + 1
			}
			if source[end] == '\\' && end+1 < n && source[end+1] != '\n' {
				end += 2
			} else {
				end++
			}
		}
	}
	for _, punctuator := range punctuators {
		if strings.HasPrefix(source[index:], punctuator) {
			return "punctuator", punctuator, index + len(punctuator)
		}
	}
	return "other", source[index : index+1], index + 1
}
func scan(source string, positions []int, start int) []LogicalLine {
	lines := []LogicalLine{}
	tokens := []Token{}
	spaced := true
	for index := 0; index < len(source); {
		switch {
		case source[index] == ' ':
			spaced = true
			index++
		case source[index] == '\n':
			end := positions[index]
			lines = append(lines, LogicalLine{tokens, start, end})
			tokens = nil
			start = end + 1
			spaced = true
			index++
		case strings.HasPrefix(source[index:], "/*"):
			end := strings.Index(source[index+2:], "*/")
			if end < 0 {
				index = len(source)
			} else {
				index += end + 4
			}
			spaced = true
		case strings.HasPrefix(source[index:], "//"):
			end := strings.IndexByte(source[index:], '\n')
			if end < 0 {
				index = len(source)
			} else {
				index += end
			}
			spaced = true
		default:
			header := len(tokens) == 2 && tokens[0].Spelling == "#" && tokens[1].Spelling == "include"
			kind, spelling, end := readToken(source, index, header)
			tokens = append(tokens, Token{Kind: kind, Spelling: spelling, Line: positions[index], Space: spaced})
			index = end
			spaced = false
		}
	}
	if len(tokens) > 0 {
		lines = append(lines, LogicalLine{tokens, start, positions[len(positions)-1]})
	}
	return lines
}
func lexSource(source string) []LogicalLine {
	characters := []byte{}
	positions := []int{}
	line := 1
	for i := 0; i < len(source); {
		if i+1 < len(source) && source[i] == '\\' && source[i+1] == '\n' {
			i += 2
			line++
			continue
		}
		c := source[i]
		characters = append(characters, c)
		positions = append(positions, line)
		if c == '\n' {
			line++
		}
		i++
	}
	return scan(string(characters), positions, 1)
}
func lexDefinition(source string, line int) []Token {
	source += "\n"
	positions := make([]int, len(source))
	for i := range positions {
		positions[i] = line
	}
	out := []Token{}
	for _, logical := range scan(source, positions, line) {
		out = append(out, logical.Tokens...)
	}
	return out
}
func render(tokens []Token) string {
	var out strings.Builder
	for i, token := range tokens {
		if i > 0 && token.Space {
			out.WriteByte(' ')
		}
		out.WriteString(token.Spelling)
	}
	return out.String()
}
func singleToken(source string) (string, bool) {
	if source == "" || strings.HasPrefix(source, "//") || strings.HasPrefix(source, "/*") {
		return "", false
	}
	kind, _, end := readToken(source, 0, false)
	return kind, end == len(source)
}
func copyTokens(tokens []Token) []Token { return append([]Token{}, tokens...) }

package main

import (
	"fmt"
	"os"
	"sort"
	"strconv"
